CREATE TABLE cb_members(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE COLLATE NOCASE,role TEXT NOT NULL CHECK(role IN ('manager','cleaner')),active INTEGER NOT NULL CHECK(active IN(0,1)),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE cb_records(kind TEXT NOT NULL,id TEXT PRIMARY KEY,revision TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)));
CREATE INDEX cb_records_kind ON cb_records(kind);
CREATE TABLE cb_approvals(id TEXT PRIMARY KEY,kind TEXT NOT NULL,record_id TEXT NOT NULL,revision TEXT NOT NULL,actor_id TEXT NOT NULL,at TEXT NOT NULL,UNIQUE(kind,record_id,revision));
CREATE TABLE cb_events(id TEXT PRIMARY KEY,actor_id TEXT NOT NULL,actor_role TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT,at TEXT NOT NULL);
CREATE TABLE cb_photos(id TEXT PRIMARY KEY,turnover_id TEXT NOT NULL UNIQUE,mime_type TEXT NOT NULL,bytes BLOB NOT NULL,sha256 TEXT NOT NULL,caption TEXT NOT NULL,uploaded_by TEXT NOT NULL,uploaded_at TEXT NOT NULL);
CREATE TABLE cb_agent_keys(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,owner_version INTEGER NOT NULL,label TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,revoked_at INTEGER);
CREATE TABLE cb_import_revisions(property_id TEXT PRIMARY KEY,revision TEXT NOT NULL);
CREATE TABLE cb_import_reviews(id TEXT PRIMARY KEY,fingerprint TEXT NOT NULL,plan TEXT NOT NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL,job_id TEXT);
