INSERT INTO cb_photos_next(id,turnover_id,position,mime_type,bytes,sha256,caption,uploaded_by,uploaded_at) SELECT id,turnover_id,0,mime_type,bytes,sha256,caption,uploaded_by,uploaded_at FROM cb_photos;
